const BASE = 'http://localhost:5000/api';

async function safeJson(url, options = {}) {
  const res = await fetch(url, options);
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`${res.status} ${res.statusText}: ${text}`);
  }
  return res.json();
}

export const api = {
  fetchStats: () => safeJson(`${BASE}/stats`),
  fetchTraders: () => safeJson(`${BASE}/traders`),
  fetchTrades: (page = 1, limit = 50) => safeJson(`${BASE}/trades?page=${page}&limit=${limit}`),
  fetchFraudCycles: () => safeJson(`${BASE}/fraud/cycles`),
  fetchRiskLogs: () => safeJson(`${BASE}/fraud/logs`),
  fetchFraudLogs: () => safeJson(`${BASE}/fraud/logs`),
  fetchTraderById: (id) => safeJson(`${BASE}/traders/${id}`),
  fetchStocks: () => safeJson(`${BASE}/stocks`),
  insertTrade: (data) =>
    safeJson(`${BASE}/trades`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    }),
};

export function normalizeArrayPayload(payload) {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.rows)) return payload.rows;
  if (Array.isArray(payload?.trades)) return payload.trades;
  if (Array.isArray(payload?.traders)) return payload.traders;
  if (Array.isArray(payload?.cycles)) return payload.cycles;
  if (Array.isArray(payload?.logs)) return payload.logs;
  return [];
}

export function inferRiskLabel(score) {
  const n = Number(score || 0);
  if (n >= 70) return 'HIGH';
  if (n >= 40) return 'MED';
  return 'LOW';
}

export function badgeClass(score) {
  const n = Number(score || 0);
  if (n >= 70) return 'badge badge-high';
  if (n >= 40) return 'badge badge-medium';
  return 'badge badge-low';
}

export function normalizeTrades(trades = [], riskLogs = []) {
  const riskMap = new Map();
  riskLogs.forEach((log) => {
    const tradeId = Number(log.trade_id);
    if (!riskMap.has(tradeId) || Number(log.risk_score || 0) > Number(riskMap.get(tradeId)?.risk_score || 0)) {
      riskMap.set(tradeId, log);
    }
  });

  return trades.map((t) => {
    const log = riskMap.get(Number(t.trade_id));
    const risk = Number(
      t.risk_score ??
      t.riskScore ??
      log?.risk_score ??
      0
    );

    return {
      ...t,
      risk_score: risk,
      risk_reason: t.reason || log?.reason || '',
      risk_detected_at: t.detected_at || log?.detected_at || null,
      risk_label: t.risk_label || log?.risk_label || inferRiskLabel(risk),
    };
  });
}

export function normalizeTraderDetail(allTrades = [], trader, riskLogs = []) {
  const traderId = Number(trader?.trader_id || trader?.id || 0);
  const mine = allTrades.filter(
    (t) => Number(t.seller_id) === traderId || Number(t.buyer_id) === traderId
  );

  const byTime = [...mine].sort((a, b) => new Date(a.timestamp || 0) - new Date(b.timestamp || 0));
  let trust = Number(trader?.trust_score ?? 100);

  const points = byTime.map((t, idx) => {
    const matchingLog = riskLogs.find((r) => Number(r.trade_id) === Number(t.trade_id));
    const risk = Number(t.risk_score ?? matchingLog?.risk_score ?? 0);
    const nextTrust = Math.max(0, Math.min(100, trust - Math.round(risk * 0.08) + (risk < 20 ? 1 : 0)));
    trust = nextTrust;
    return {
      x: idx + 1,
      trade_id: t.trade_id,
      risk_score: risk,
      trust_score: nextTrust,
      timestamp: t.timestamp,
    };
  });

  const predictedTrust = points.length
    ? Math.max(0, Math.round(points.slice(-5).reduce((a, b) => a + b.trust_score, 0) / Math.min(5, points.length) - 3))
    : Number(trader?.trust_score ?? 100);

  return {
    trades: byTime,
    chartPoints: points,
    predictedTrust,
    totalTrades: byTime.length,
    totalBuys: byTime.filter((t) => Number(t.buyer_id) === traderId).length,
    totalSells: byTime.filter((t) => Number(t.seller_id) === traderId).length,
    avgRisk: byTime.length
      ? Math.round(byTime.reduce((s, t) => s + Number(t.risk_score || 0), 0) / byTime.length)
      : 0,
  };
}
